// BalanceService.java — naive (unsafe) vs optimistic vs CAS debits
package com.nbi.db;

import java.util.concurrent.atomic.AtomicReference;

public class BalanceService {

    // UNSAFE: read-modify-write with no concurrency control -> lost updates.
    public synchronizedUnsafeMarker unsafe = null; // (placeholder to document intent)
    public interface synchronizedUnsafeMarker {}

    // OPTIMISTIC: UPDATE ... SET balance=?, version=version+1 WHERE id=? AND version=:read
    // Returns true if applied; false means a conflict occurred (caller retries).
    public boolean debitOptimistic(VersionedAccount a, double amount) {
        long readVersion = a.version;      // read current version
        double readBalance = a.balance;    // read current balance
        if (readBalance < amount) return true; // (treat as handled: insufficient)
        // simulate the atomic conditional UPDATE WHERE version = readVersion
        synchronized (a) {                 // stands in for the DB's atomic row update
            if (a.version != readVersion) return false; // conflict -> retry
            a.balance = readBalance - amount;
            a.version = readVersion + 1;   // bump version
            return true;
        }
    }

    // CAS: lock-free atomic update of an in-memory cached balance.
    public void debitCas(AtomicReference<Double> cached, double amount) {
        Double prev, next;
        do {
            prev = cached.get();                 // expected
            next = prev - amount;                // computed
        } while (!cached.compareAndSet(prev, next)); // apply only if unchanged
    }
}
