// Demo.java — runs concurrent debits and shows safe vs unsafe outcomes
package com.nbi.db;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

public class Demo {
    public static void main(String[] args) throws Exception {
        BalanceService svc = new BalanceService();

        // --- Optimistic locking under concurrency (with retry) ---
        VersionedAccount acct = new VersionedAccount("A100", 1000);
        int threads = 10, debit = 100;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch latch = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            pool.submit(() -> {
                while (!svc.debitOptimistic(acct, debit)) { /* conflict: retry */ }
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();
        System.out.println("Optimistic: 10 x 100 debited from 1000 -> balance = "
                + acct.balance + " (version " + acct.version + ")");

        // --- CAS in-memory counter ---
        AtomicReference<Double> cached = new AtomicReference<>(1000.0);
        ExecutorService pool2 = Executors.newFixedThreadPool(threads);
        CountDownLatch latch2 = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            pool2.submit(() -> { svc.debitCas(cached, debit); latch2.countDown(); });
        }
        latch2.await();
        pool2.shutdown();
        System.out.println("CAS:        10 x 100 debited from 1000 -> balance = " + cached.get());
    }
}
